import type { EditorState } from '@codemirror/state'
import {
  type EditorView,
  showTooltip,
  type Tooltip,
  type TooltipView,
  type ViewUpdate,
} from '@codemirror/view'
import { describeError } from '../suggestions/error-message'
import { freeTextInstruction } from '../suggestions/instruction'
import { findSuggestion } from '../suggestions/state'
import type { ReadySuggestion, SuggestionId } from '../suggestions/types'
import { detectApplePlatform, formatShortcut } from '../ui/platform'
import { el } from './dom'
import { interactionField } from './interaction-state'
import {
  closeRefineEffect,
  openRefineEffect,
  refineInputOpenFor,
} from './refine-input'
import {
  acceptSuggestionById,
  rejectSuggestionById,
} from './suggestion-commands'
import {
  activeOf,
  cursorOf,
  suggestionsField,
  suggestionsOf,
} from './suggestion-field'
import { suggestionActionsFacet } from './suggestion-runtime'

type CardContent = {
  readonly suggestion: ReadySuggestion
  readonly showRationale: boolean
  readonly showActions: boolean
  readonly refineOpen: boolean
}

type CardKind = 'active' | 'hover'

const contentFor = (
  kind: CardKind,
  state: EditorState,
): CardContent | undefined => {
  const hoveredId = state.field(interactionField).hoveredId
  const active = activeOf(state)
  if (kind === 'active') {
    if (!active) return undefined
    const cursorInside =
      active.from <= cursorOf(state) && cursorOf(state) <= active.to
    return {
      suggestion: active,
      showRationale: cursorInside || hoveredId === active.id,
      showActions: true,
      refineOpen: refineInputOpenFor(state) === active.id,
    }
  }
  if (hoveredId === null || hoveredId === active?.id) return undefined
  const hovered = findSuggestion(suggestionsOf(state), hoveredId)
  return hovered?.status === 'ready'
    ? {
        suggestion: hovered,
        showRationale: true,
        showActions: false,
        refineOpen: false,
      }
    : undefined
}

const refineKey = ({ refine }: ReadySuggestion): string =>
  refine.status === 'failed'
    ? `failed:${describeError(refine.error)}`
    : refine.status

const contentKey = ({
  suggestion,
  showRationale,
  showActions,
  refineOpen,
}: CardContent): string =>
  [
    suggestion.id,
    suggestion.rationale,
    showRationale,
    showActions,
    refineOpen,
    refineKey(suggestion),
  ].join('\u0000')

const shortcutLabel = (key: string): string =>
  formatShortcut(key, detectApplePlatform())

type ButtonOptions = {
  readonly refocus?: boolean
  readonly disabled?: boolean
  readonly busy?: boolean
  readonly expanded?: boolean
}

const actionButton = (
  view: EditorView,
  label: string,
  hint: string | undefined,
  run: () => void,
  {
    refocus = true,
    disabled = false,
    busy = false,
    expanded,
  }: ButtonOptions = {},
) =>
  el(
    'button',
    {
      class: 'cm-ai-button',
      attrs: {
        type: 'button',
        ...(disabled && { disabled: '' }),
        ...(busy && { 'aria-busy': 'true' }),
        ...(expanded !== undefined && { 'aria-expanded': String(expanded) }),
      },
      on: {
        mousedown: (event) => event.preventDefault(),
        click: () => {
          run()
          if (refocus) view.focus()
        },
      },
    },
    hint === undefined
      ? [label]
      : [label, el('kbd', { class: 'cm-ai-kbd' }, [hint])],
  )

type RefineForm = {
  readonly form: HTMLFormElement
  readonly input: HTMLInputElement
}

const createRefineForm = (view: EditorView): RefineForm => {
  const input = el('input', {
    class: 'cm-ai-bubble-input',
    attrs: {
      type: 'text',
      placeholder: 'Refine: make it shorter…',
      'aria-label': 'Refine instruction',
      autocomplete: 'off',
      spellcheck: 'false',
    },
    on: {
      keydown: (event) => {
        if (event.key === 'Escape') {
          event.preventDefault()
          event.stopPropagation()
          input.value = ''
          view.dispatch({ effects: closeRefineEffect.of(null) })
          view.focus()
        } else if (event.key === 'k' && (event.metaKey || event.ctrlKey)) {
          event.preventDefault()
        }
      },
    },
  })
  const form = el(
    'form',
    {
      class: 'cm-ai-refine',
      on: {
        submit: (event) => {
          event.preventDefault()
          const id = refineInputOpenFor(view.state)
          const text = input.value.trim()
          if (id === null || text === '') return
          input.value = ''
          view.state
            .facet(suggestionActionsFacet)
            ?.refine(view, id, freeTextInstruction(text))
          view.focus()
        },
      },
    },
    [input],
  )
  return { form, input }
}

const refineButton = (
  view: EditorView,
  { suggestion, refineOpen }: CardContent,
) =>
  suggestion.refine.status === 'working'
    ? actionButton(view, 'Refining…', undefined, () => undefined, {
        disabled: true,
        busy: true,
      })
    : actionButton(
        view,
        'Refine',
        shortcutLabel('K'),
        () =>
          view.dispatch({
            effects: refineOpen
              ? closeRefineEffect.of(null)
              : openRefineEffect.of(suggestion.id),
          }),
        { refocus: refineOpen, expanded: refineOpen },
      )

const refineError = (
  view: EditorView,
  { refine, id }: ReadySuggestion,
  withRetry: boolean,
) =>
  refine.status === 'failed'
    ? [
        el('div', { class: 'cm-ai-card-error', attrs: { role: 'alert' } }, [
          el('span', { class: 'cm-ai-error-message' }, [
            describeError(refine.error),
          ]),
          ...(withRetry
            ? [
                actionButton(view, 'Retry', undefined, () =>
                  view.state
                    .facet(suggestionActionsFacet)
                    ?.retryRefine(view, id),
                ),
              ]
            : []),
        ]),
      ]
    : []

const renderCard = (
  view: EditorView,
  content: CardContent,
  { form }: RefineForm,
): Node[] => {
  const { suggestion, showRationale, showActions, refineOpen } = content
  return [
    ...(showRationale
      ? [el('p', { class: 'cm-ai-rationale' }, [suggestion.rationale])]
      : []),
    ...(showActions
      ? [
          el('div', { class: 'cm-ai-card-actions' }, [
            actionButton(view, 'Accept', shortcutLabel('↵'), () =>
              acceptSuggestionById(view, suggestion.id),
            ),
            actionButton(view, 'Reject', 'Esc', () =>
              rejectSuggestionById(view, suggestion.id),
            ),
            refineButton(view, content),
          ]),
          ...(refineOpen ? [form] : []),
        ]
      : []),
    ...refineError(view, suggestion, showActions),
  ]
}

const openedRefine = (update: ViewUpdate): boolean =>
  update.transactions.some((transaction) =>
    transaction.effects.some((effect) => effect.is(openRefineEffect)),
  )

const cardCreator =
  (kind: CardKind) =>
  (view: EditorView): TooltipView => {
    const refineForm = createRefineForm(view)
    const dom = el('div', {
      class: `cm-ai-card cm-ai-card-${kind}`,
      attrs:
        kind === 'active' ? { role: 'group', 'aria-label': 'Suggestion' } : {},
      on: {
        mousedown: (event) => {
          if (event.target !== refineForm.input) event.preventDefault()
        },
      },
    })
    let renderedKey = ''
    let formOwner: SuggestionId | null = null
    const syncFormOwner = (state: EditorState): void => {
      const next = refineInputOpenFor(state)
      if (next === formOwner) return
      formOwner = next
      refineForm.input.value = ''
    }
    const sync = (state: EditorState): void => {
      syncFormOwner(state)
      const content = contentFor(kind, state)
      if (!content) return
      const key = contentKey(content)
      if (key === renderedKey) return
      renderedKey = key
      const hadFocus =
        refineForm.input.ownerDocument.activeElement === refineForm.input
      dom.replaceChildren(...renderCard(view, content, refineForm))
      if (hadFocus && refineForm.form.isConnected) refineForm.input.focus()
    }
    sync(view.state)
    return {
      dom,
      update: (update) => {
        sync(update.state)
        if (openedRefine(update) && refineForm.form.isConnected)
          refineForm.input.focus()
      },
    }
  }

const createActiveCard = cardCreator('active')
const createHoverCard = cardCreator('hover')

const tooltipFor = (
  kind: CardKind,
  state: EditorState,
  create: (view: EditorView) => TooltipView,
): Tooltip | null => {
  const content = contentFor(kind, state)
  return content ? { pos: content.suggestion.from, above: true, create } : null
}

export const suggestionCards = showTooltip.computeN(
  [suggestionsField, interactionField, 'selection'],
  (state) => [
    tooltipFor('active', state, createActiveCard),
    tooltipFor('hover', state, createHoverCard),
  ],
)
import type { EditorState, Range } from '@codemirror/state'
import {
  Decoration,
  type DecorationSet,
  EditorView,
  WidgetType,
} from '@codemirror/view'
import { describeError } from '../suggestions/error-message'
import type {
  ReadySuggestion,
  Suggestion,
  SuggestionId,
} from '../suggestions/types'
import { bubbleField, targetPreviewRange } from './ask-bubble'
import { el } from './dom'
import { rejectSuggestionById } from './suggestion-commands'
import { activeOf, suggestionsField, suggestionsOf } from './suggestion-field'
import { suggestionActionsFacet } from './suggestion-runtime'

const idAttributes = (id: SuggestionId) => ({ 'data-suggestion-id': id })

const classNames = (...names: readonly (string | false)[]): string =>
  names.filter((name) => name !== false).join(' ')

class InsertedWidget extends WidgetType {
  constructor(
    readonly id: SuggestionId,
    readonly text: string,
    readonly separated: boolean,
    readonly refining: boolean,
  ) {
    super()
  }

  eq(other: InsertedWidget): boolean {
    return (
      other.id === this.id &&
      other.text === this.text &&
      other.separated === this.separated &&
      other.refining === this.refining
    )
  }

  toDOM(): HTMLElement {
    return el(
      'ins',
      {
        class: classNames(
          'cm-ai-inserted',
          this.separated && 'cm-ai-inserted-separated',
          this.refining && 'cm-ai-refining',
        ),
        attrs: idAttributes(this.id),
      },
      [this.text],
    )
  }

  ignoreEvent(): boolean {
    return false
  }
}

class ReplacementWidget extends WidgetType {
  constructor(
    readonly id: SuggestionId,
    readonly text: string,
    readonly refining: boolean,
  ) {
    super()
  }

  eq(other: ReplacementWidget): boolean {
    return (
      other.id === this.id &&
      other.text === this.text &&
      other.refining === this.refining
    )
  }

  toDOM(): HTMLElement {
    return el(
      'div',
      {
        class: classNames(
          'cm-ai-replacement',
          this.refining && 'cm-ai-refining',
        ),
        attrs: idAttributes(this.id),
      },
      [el('ins', {}, [this.text])],
    )
  }

  ignoreEvent(): boolean {
    return false
  }
}

class ErrorCardWidget extends WidgetType {
  constructor(
    readonly id: SuggestionId,
    readonly message: string,
  ) {
    super()
  }

  eq(other: ErrorCardWidget): boolean {
    return other.id === this.id && other.message === this.message
  }

  toDOM(view: EditorView): HTMLElement {
    const button = (label: string, onClick: () => void) =>
      el(
        'button',
        {
          class: 'cm-ai-button',
          attrs: { type: 'button' },
          on: {
            mousedown: (event) => event.preventDefault(),
            click: () => {
              onClick()
              view.focus()
            },
          },
        },
        [label],
      )
    return el(
      'div',
      {
        class: 'cm-ai-error',
        attrs: { role: 'alert', ...idAttributes(this.id) },
      },
      [
        el('span', { class: 'cm-ai-error-message' }, [this.message]),
        el('span', { class: 'cm-ai-error-actions' }, [
          button('Retry', () =>
            view.state.facet(suggestionActionsFacet)?.retry(view, this.id),
          ),
          button('Dismiss', () => rejectSuggestionById(view, this.id)),
        ]),
      ],
    )
  }

  ignoreEvent(): boolean {
    return true
  }
}

const pendingMark = (id: SuggestionId) =>
  Decoration.mark({
    class: 'cm-ai-pending',
    attributes: idAttributes(id),
  })

const failedMark = (id: SuggestionId) =>
  Decoration.mark({
    class: 'cm-ai-failed',
    attributes: idAttributes(id),
  })

const suggestionMark = (
  id: SuggestionId,
  active: boolean,
  refineFailed: boolean,
) =>
  Decoration.mark({
    class: classNames(
      'cm-ai-suggestion',
      active && 'cm-ai-active',
      refineFailed && 'cm-ai-refine-failed',
    ),
    attributes: idAttributes(id),
  })

const deletedMark = (id: SuggestionId, refining: boolean) =>
  Decoration.mark({
    tagName: 'del',
    class: classNames('cm-ai-deleted', refining && 'cm-ai-refining'),
    attributes: idAttributes(id),
  })

const readyRanges = (
  suggestion: ReadySuggestion,
  active: boolean,
): readonly Range<Decoration>[] => {
  const { id, from, to, diff } = suggestion
  const refining = suggestion.refine.status === 'working'
  const hunks = diff.hunks.flatMap((hunk, index): Range<Decoration>[] => {
    if (hunk.type === 'deleted') {
      return hunk.from === hunk.to
        ? []
        : [deletedMark(id, refining).range(from + hunk.from, from + hunk.to)]
    }
    if (hunk.type !== 'inserted') return []
    if (diff.mode === 'block') {
      return [
        Decoration.widget({
          widget: new ReplacementWidget(id, hunk.text, refining),
          block: true,
          side: 1,
        }).range(to),
      ]
    }
    const separated = diff.hunks[index - 1]?.type === 'deleted'
    return [
      Decoration.widget({
        widget: new InsertedWidget(id, hunk.text, separated, refining),
        side: 1,
      }).range(from + hunk.at),
    ]
  })
  return [
    suggestionMark(id, active, suggestion.refine.status === 'failed').range(
      from,
      to,
    ),
    ...hunks,
  ]
}

const suggestionRanges = (
  suggestion: Suggestion,
  active: boolean,
): readonly Range<Decoration>[] => {
  switch (suggestion.status) {
    case 'pending':
      return [pendingMark(suggestion.id).range(suggestion.from, suggestion.to)]
    case 'error':
      return [
        failedMark(suggestion.id).range(suggestion.from, suggestion.to),
        Decoration.widget({
          widget: new ErrorCardWidget(
            suggestion.id,
            describeError(suggestion.error),
          ),
          block: true,
          side: 1,
        }).range(suggestion.to),
      ]
    case 'ready':
      return readyRanges(suggestion, active)
  }
}

const targetPreview = Decoration.mark({ class: 'cm-ai-target-preview' })

export const buildDecorations = (state: EditorState): DecorationSet => {
  const active = activeOf(state)
  const preview = targetPreviewRange(state)
  return Decoration.set(
    [
      ...suggestionsOf(state).items.flatMap((suggestion) =>
        suggestionRanges(suggestion, suggestion.id === active?.id),
      ),
      ...(preview ? [targetPreview.range(preview.from, preview.to)] : []),
    ],
    true,
  )
}

export const suggestionDecorations = EditorView.decorations.compute(
  [suggestionsField, bubbleField, 'selection'],
  buildDecorations,
)
import { Prec } from '@codemirror/state'
import { keymap } from '@codemirror/view'
import { bubbleVisible, dismissBubbleEffect, openAskEffect } from './ask-bubble'
import { currentTarget } from './current-target'
import {
  closeRefineEffect,
  openRefineEffect,
  refineInputOpenFor,
} from './refine-input'
import {
  acceptAtCursor,
  type EditorHandle,
  rejectAtCursor,
} from './suggestion-commands'
import {
  activeAtCursor,
  cancelRefineEffect,
  suggestionAtCursor,
} from './suggestion-field'

const openAsk = (handle: EditorHandle): boolean => {
  if (currentTarget(handle.state) === undefined) return false
  handle.dispatch({ effects: openAskEffect.of(null) })
  return true
}

export const openAskOrRefine = (handle: EditorHandle): boolean => {
  const active = activeAtCursor(handle.state)
  if (active === undefined || !handle.state.selection.main.empty)
    return openAsk(handle)
  if (active.refine.status === 'working') return false
  handle.dispatch({ effects: openRefineEffect.of(active.id) })
  return true
}

const closeRefineInput = (handle: EditorHandle): boolean => {
  if (refineInputOpenFor(handle.state) === null) return false
  handle.dispatch({ effects: closeRefineEffect.of(null) })
  return true
}

const cancelRefineAtCursor = (handle: EditorHandle): boolean => {
  const found = suggestionAtCursor(handle.state)
  if (found?.status !== 'ready' || found.refine.status === 'idle') return false
  handle.dispatch({ effects: cancelRefineEffect.of(found.id) })
  return true
}

const dismissBubble = (handle: EditorHandle): boolean => {
  if (!bubbleVisible(handle.state)) return false
  handle.dispatch({ effects: dismissBubbleEffect.of(null) })
  return true
}

export const escapeAtCursor = (handle: EditorHandle): boolean =>
  dismissBubble(handle) ||
  closeRefineInput(handle) ||
  cancelRefineAtCursor(handle) ||
  rejectAtCursor(handle)

export const suggestionKeymap = Prec.highest(
  keymap.of([
    { key: 'Mod-k', run: openAskOrRefine, preventDefault: true },
    { key: 'Mod-Enter', run: acceptAtCursor },
    { key: 'Escape', run: escapeAtCursor },
  ]),
)
