import type { Block } from './extract-blocks'

export type Selection = {
  readonly from: number
  readonly to: number
}

export type Target = {
  readonly source: 'selection' | 'block'
  readonly from: number
  readonly to: number
  readonly text: string
  readonly blocks: readonly Block[]
}

export type Neighbors = {
  readonly title?: string
  readonly section?: string
  readonly before: readonly Block[]
  readonly after: readonly Block[]
}

const NEIGHBOR_COUNT = 2

export const findBlockAt = (
  blocks: readonly Block[],
  position: number,
): Block | undefined =>
  blocks.find((block) => block.from <= position && position <= block.to)

const distanceTo = (block: Block, position: number): number =>
  position < block.from ? block.from - position : position - block.to

const nearestBlock = (
  blocks: readonly Block[],
  position: number,
): Block | undefined =>
  blocks.reduce<Block | undefined>(
    (best, block) =>
      best === undefined ||
      distanceTo(block, position) < distanceTo(best, position)
        ? block
        : best,
    undefined,
  )

export const headingText = (block: Block): string => {
  const lines = block.text.split('\n')
  const content = lines[0]?.startsWith('#')
    ? lines[0].replace(/^#{1,6}[ \t]*/, '').replace(/[ \t]+#+[ \t]*$/, '')
    : lines.slice(0, -1).join(' ')
  return content.trim()
}

const overlaps = (block: Block, from: number, to: number): boolean =>
  block.from < to && block.to > from

const LEADING_BREAKS = /^[\r\n]*/
const TRAILING_BREAKS = /[\r\n]*$/

const resolveSelectionTarget = (
  blocks: readonly Block[],
  text: string,
  selection: Selection,
): Target | undefined => {
  const selected = text.slice(selection.from, selection.to)
  if (selected.trim() === '') return undefined
  const from = selection.from + (LEADING_BREAKS.exec(selected)?.[0].length ?? 0)
  const to = selection.to - (TRAILING_BREAKS.exec(selected)?.[0].length ?? 0)
  return {
    source: 'selection',
    from,
    to,
    text: text.slice(from, to),
    blocks: blocks.filter((block) => overlaps(block, from, to)),
  }
}

const resolveCursorTarget = (
  blocks: readonly Block[],
  position: number,
): Target | undefined => {
  const block = findBlockAt(blocks, position) ?? nearestBlock(blocks, position)
  return block === undefined
    ? undefined
    : {
        source: 'block',
        from: block.from,
        to: block.to,
        text: block.text,
        blocks: [block],
      }
}

export const targetFromRange = (
  blocks: readonly Block[],
  text: string,
  { from, to }: Selection,
  source: Target['source'],
): Target => ({
  source,
  from,
  to,
  text: text.slice(from, to),
  blocks: blocks.filter((block) => overlaps(block, from, to)),
})

export const resolveTarget = (
  blocks: readonly Block[],
  text: string,
  selection: Selection,
): Target | undefined => {
  const from = Math.max(0, Math.min(selection.from, selection.to))
  const to = Math.min(text.length, Math.max(selection.from, selection.to))
  return from === to
    ? resolveCursorTarget(blocks, from)
    : resolveSelectionTarget(blocks, text, { from, to })
}

const anchorRange = (target: Target): Selection => ({
  from: Math.min(target.from, ...target.blocks.map((block) => block.from)),
  to: Math.max(target.to, ...target.blocks.map((block) => block.to)),
})

export const getNeighbors = (
  blocks: readonly Block[],
  target: Target,
): Neighbors => {
  const { from, to } = anchorRange(target)
  const preceding = blocks.filter((block) => block.to <= from)
  const following = blocks.filter((block) => block.from >= to)
  const title = blocks.find(
    (block) => block.kind === 'heading' && block.level === 1,
  )
  const section = preceding.findLast((block) => block.kind === 'heading')
  return {
    ...(title && { title: headingText(title) }),
    ...(section && { section: headingText(section) }),
    before: preceding.slice(-NEIGHBOR_COUNT),
    after: following.slice(0, NEIGHBOR_COUNT),
  }
}
import { APICallError, NoObjectGeneratedError, RetryError } from 'ai'

export type ClientError =
  | { readonly type: 'out-of-credit'; readonly message: string }
  | { readonly type: 'rate-limited'; readonly message: string }
  | { readonly type: 'timeout'; readonly message: string }
  | { readonly type: 'aborted'; readonly message: string }
  | { readonly type: 'network'; readonly message: string }
  | { readonly type: 'invalid-output'; readonly message: string }
  | {
      readonly type: 'api'
      readonly status: number
      readonly message: string
    }
  | { readonly type: 'unknown'; readonly message: string }

export type Result<T> =
  | { readonly ok: true; readonly value: T }
  | { readonly ok: false; readonly error: ClientError }

const messageOf = (error: unknown): string =>
  error instanceof Error ? error.message : String(error)

const payloadStatus = (data: unknown): number | undefined => {
  if (typeof data !== 'object' || data === null) return undefined
  const code = (data as { code?: unknown }).code
  return typeof code === 'number' ? code : undefined
}

const fromStatus = (status: number, message: string): ClientError =>
  status === 402
    ? { type: 'out-of-credit', message }
    : status === 429
      ? { type: 'rate-limited', message }
      : { type: 'api', status, message }

const fromApiCallError = (error: APICallError): ClientError => {
  const status =
    error.statusCode === undefined || error.statusCode === 200
      ? (payloadStatus(error.data) ?? error.statusCode)
      : error.statusCode
  return status === undefined
    ? { type: 'network', message: error.message }
    : fromStatus(status, error.message)
}

const fromDirectError = (error: unknown): ClientError | undefined => {
  if (RetryError.isInstance(error)) return classifyError(error.lastError)
  if (APICallError.isInstance(error)) return fromApiCallError(error)
  if (NoObjectGeneratedError.isInstance(error))
    return { type: 'invalid-output', message: error.message }
  if (error instanceof Error && error.name === 'TimeoutError')
    return { type: 'timeout', message: error.message }
  if (error instanceof Error && error.name === 'AbortError')
    return { type: 'aborted', message: error.message }
  if (error instanceof TypeError && /fetch/i.test(error.message))
    return { type: 'network', message: error.message }
  return undefined
}

export const classifyError = (error: unknown): ClientError => {
  const direct = fromDirectError(error)
  if (direct) return direct
  if (error instanceof Error && error.cause !== undefined) {
    const nested = classifyError(error.cause)
    if (nested.type !== 'unknown') return nested
  }
  return { type: 'unknown', message: messageOf(error) }
}

export const isRetryableOutputError = (error: ClientError): boolean =>
  error.type === 'invalid-output'
