  it('drops them all with Reject all', async () => {
    const { handle } = await afterPass()

    expect(rejectAllReviewSuggestions(handle)).toBe(true)

    expect(idsOf(handle)).toEqual([])
    expect(handle.state.doc.toString()).toBe(DOC)
