export function EditorPane({
  initialDoc,
  onChange,
  onNotice,
  onReviewStatus,
  onReviewNotice,
  onReviewControls,
}: EditorPaneProps) {
  const parentRef = useRef<HTMLDivElement>(null)
  const initialDocRef = useRef(initialDoc)
  const handlersRef = useRef({
    onChange,
    onNotice,
    onReviewStatus,
    onReviewNotice,
    onReviewControls,
  })

  useEffect(() => {
    handlersRef.current = {
      onChange,
      onNotice,
      onReviewStatus,
      onReviewNotice,
      onReviewControls,
    }
  }, [onChange, onNotice, onReviewStatus, onReviewNotice, onReviewControls])

  useEffect(() => {
    const parent = parentRef.current
    if (!parent) return undefined
    const view = createEditorView({
      parent,
      doc: initialDocRef.current,
      onChange: (doc) => handlersRef.current.onChange(doc),
      extensions: suggestionExtensions({
        client: createLazyModelClient(() =>
          import('../ai/browser-client').then((module) =>
