const ids = () => new Set([...document.querySelectorAll('.cm-ai-suggestion')].map((e) => e.dataset.suggestionId))
const obs = new MutationObserver(() => {
  const n = ids().size
  const last = window.__t.shown.at(-1)
  const now = performance.now()
  if (n > (last?.count ?? 0)) {
