  state: SuggestionsState,
): readonly SuggestionId[] =>
  state.items.filter(isInFlight).map((item) => item.id)

const contains = (item: Suggestion, position: number): boolean =>
  item.from <= position && position <= item.to

const mostRecent = <T extends Suggestion>(items: readonly T[]): T | undefined =>
  items.reduce<T | undefined>(
    (best, item) =>
      best === undefined || item.sequence > best.sequence ? item : best,
    undefined,
  )

export const activeSuggestion = (
  state: SuggestionsState,
  cursor: number | null,
): ReadySuggestion | undefined => {
  const ready = state.items.filter(
    (item): item is ReadySuggestion => item.status === 'ready',
  )
  const containing =
    cursor === null ? [] : ready.filter((item) => contains(item, cursor))
  return mostRecent(containing) ?? mostRecent(ready)
}

export const suggestionAt = (
  state: SuggestionsState,
  position: number,
): Suggestion | undefined =>
  mostRecent(state.items.filter((item) => contains(item, position)))
  if (typeof data !== 'object' || data === null) return undefined
  const code = (data as { code?: unknown }).code
  return typeof code === 'number' ? code : undefined
}

const fromStatus = (status: number, message: string): ClientError =>
  status === 402
    ? { type: 'out-of-credit', message }
    : status === 429
      ? { type: 'rate-limited', message }
      : { type: 'api', status, message }

const fromApiCallError = (error: APICallError): ClientError => {
  const status =
    error.statusCode === undefined || error.statusCode === 200
      ? (payloadStatus(error.data) ?? error.statusCode)
      : error.statusCode
  return status === undefined
    ? { type: 'network', message: error.message }
    : fromStatus(status, error.message)
}

const fromDirectError = (error: unknown): ClientError | undefined => {
  if (RetryError.isInstance(error)) return classifyError(error.lastError)
  if (APICallError.isInstance(error)) return fromApiCallError(error)
  if (NoObjectGeneratedError.isInstance(error))
    return { type: 'invalid-output', message: error.message }
  if (error instanceof Error && error.name === 'TimeoutError')
    return { type: 'timeout', message: error.message }
  if (error instanceof Error && error.name === 'AbortError')
    return { type: 'aborted', message: error.message }
  if (error instanceof TypeError && /fetch/i.test(error.message))
    return { type: 'network', message: error.message }
  return undefined
}

import type { Block } from '../blocks/extract-blocks'
import type { ReviewEdit, SuggestionOutput } from './schemas'

export const MAX_REVIEW_EDITS = 6
export const JUNK_MIN_ORIGINAL_WORDS = 15
export const JUNK_MAX_REPLACEMENT_WORDS = 3

const WORD = /[\p{L}\p{N}]+(?:['’-][\p{L}\p{N}]+)*/gu

const wordCount = (text: string): number => text.match(WORD)?.length ?? 0

export const isJunkReplacement = (
  original: string,
  replacement: string,
): boolean =>
  wordCount(original) > JUNK_MIN_ORIGINAL_WORDS &&
  wordCount(replacement) < JUNK_MAX_REPLACEMENT_WORDS

export type DropReason =
  | 'unknown-block'
  | 'code-block'
  | 'occupied'
  | 'duplicate-block'
  | 'empty'
  | 'unchanged'
  | 'junk'
  | 'over-limit'

export type ValidatedEdit = ReviewEdit & { readonly block: Block }

    },
    outcome: { type: 'validated', edit: { ...edit, block } },
  }
}

export const validateReviewEdits = (
  edits: readonly ReviewEdit[],
  blocks: readonly Block[],
  occupied: ReadonlySet<string> = new Set(),
): {
  readonly validated: readonly ValidatedEdit[]
  readonly dropped: readonly DroppedEdit[]
} => {
  const context = { blocks, occupied }
  const validated: ValidatedEdit[] = []
  const dropped: DroppedEdit[] = []
  let state = initialReviewState
  for (const edit of edits) {
    const step = validateReviewEdit(context, state, edit)
    state = step.state
    if (step.outcome.type === 'validated') validated.push(step.outcome.edit)
    else dropped.push({ edit: step.outcome.edit, reason: step.outcome.reason })
  }
  return { validated, dropped }
}

export type SuggestionResult = SuggestionOutput & {
  readonly unchanged: boolean
}

export type SuggestionCheck =
  | { readonly type: 'valid'; readonly suggestion: SuggestionResult }
  | { readonly type: 'invalid'; readonly reason: 'empty' }

export const checkSuggestion = (
  original: string,

  it('maps other HTTP failures to api with the status', () => {
    expect(classifyError(apiError(500))).toMatchObject({
      type: 'api',
      status: 500,
    })
  })

  it('maps a failed connection to network', () => {
    expect(classifyError(apiError(undefined)).type).toBe('network')
  })

  it('reads the status from an error payload sent with HTTP 200', () => {
    expect(classifyError(apiError(200, { code: 402 })).type).toBe(
      'out-of-credit',
    )
    expect(classifyError(apiError(200, { code: 429 })).type).toBe(
      'rate-limited',
    )
  })

  it('maps a browser fetch failure to network', () => {
    expect(classifyError(new TypeError('Failed to fetch')).type).toBe('network')
  })

  it('maps a timeout to timeout', () => {
    const error = new DOMException('The operation timed out.', 'TimeoutError')
    expect(classifyError(error).type).toBe('timeout')
  })

  it('maps an abort to aborted', () => {
    const error = new DOMException('Aborted', 'AbortError')
    expect(classifyError(error).type).toBe('aborted')
  })

  it('maps a schema failure to invalid-output', () => {
    expect(classifyError(noObject()).type).toBe('invalid-output')
  })

  it('unwraps a RetryError to its last error', () => {
    const wrapped = new RetryError({
      message: 'failed after retries',
      reason: 'maxRetriesExceeded',
      errors: [apiError(500), apiError(429)],
    })
    expect(classifyError(wrapped).type).toBe('rate-limited')
  })

  it('finds a classified error in the cause chain', () => {
    const outer = new Error('wrapper', { cause: apiError(402) })
    expect(classifyError(outer).type).toBe('out-of-credit')
  })

  it('falls back to unknown with the message', () => {
    expect(classifyError(new Error('boom'))).toEqual({
      type: 'unknown',
      message: 'boom',
    })
    expect(classifyError('plain string').type).toBe('unknown')
  })
})

